using BC.FixedAsset.Services;using System;using System.Data;using System.Text;using System.Web.UI;using System.Web.UI.WebControls;
namespace BC.FixedAsset.Web.FixedAsset.Survey{public partial class SurveyList:SecurePage{
protected TextBox txtSearch;protected DropDownList ddlStatus;protected GridView gridSurvey;protected Button btnSearch,btnExport,btnClose;protected Label lblMessage;protected Panel pnlDetail;protected Literal litDetail;protected Repeater repImages;private readonly AssetSurveyService service=new AssetSurveyService();
protected void Page_Load(object s,EventArgs e){if(!IsPostBack)Bind();}protected void Search_Click(object s,EventArgs e)=>Bind();private DataTable Data()=>service.Search(txtSearch.Text,ddlStatus.SelectedValue,AssetAccess);private void Bind(){gridSurvey.DataSource=Data();gridSurvey.DataBind();}
protected void Grid_RowDataBound(object sender,GridViewRowEventArgs e){if(e.Row.RowType!=DataControlRowType.DataRow)return;var detail=e.Row.FindControl("btnDetail") as LinkButton;if(detail==null)return;e.Row.CssClass="clickable-survey-row";e.Row.Attributes["tabindex"]="0";e.Row.Attributes["role"]="button";e.Row.Attributes["aria-label"]="ดูรายละเอียดรายการ "+Convert.ToString(DataBinder.Eval(e.Row.DataItem,"SurveyNo"));e.Row.Attributes["data-detail-trigger"]=detail.ClientID;}
protected string AttachmentUrl(object id)=>id==null||id==DBNull.Value?ResolveUrl("~/Assets/default-profile.svg"):ResolveUrl("~/Attachment.ashx?id="+id);protected bool CanEdit(object status)=>Convert.ToString(status)=="Draft"||Convert.ToString(status)=="Returned";protected string Dimension(object w,object l,object h)=>string.Format("{0} × {1} × {2} cm",w==DBNull.Value?"-":w,l==DBNull.Value?"-":l,h==DBNull.Value?"-":h);
protected void Grid_RowCommand(object sender,GridViewCommandEventArgs e){try{var id=Convert.ToInt64(e.CommandArgument);if(e.CommandName=="DeleteSurvey"){service.Delete(id,AssetAccess,Server.MapPath(System.Configuration.ConfigurationManager.AppSettings["UploadRoot"]));Bind();lblMessage.Text="ลบรายการเรียบร้อย";}else if(e.CommandName=="Detail"){var t=service.Detail(id,AssetAccess);if(t.Rows.Count==0)throw new InvalidOperationException("ไม่พบข้อมูลหรือไม่มีสิทธิ์");var r=t.Rows[0];litDetail.Text="<dl class='detail-grid'><dt>เลขที่</dt><dd>"+H(r["SurveyNo"])+"</dd><dt>ทรัพย์สิน</dt><dd>"+H(r["AssetName"])+"</dd><dt>Serial</dt><dd>"+H(r["SerialNumber"])+"</dd><dt>ขนาด</dt><dd>"+H(Dimension(r["WidthCm"],r["LengthCm"],r["HeightCm"]))+"</dd><dt>น้ำหนัก</dt><dd>"+H(r["WeightKg"])+" kg</dd><dt>จำนวน</dt><dd>"+H(r["Quantity"])+" "+H(r["UomCode"])+"</dd><dt>สถานที่</dt><dd>"+H(r["BuildingName"])+" / "+H(r["FloorName"])+" / "+H(r["RoomName"])+"</dd><dt>ผู้รับผิดชอบ</dt><dd>"+H(r["Custodian"])+"</dd><dt>ผู้สร้าง</dt><dd>"+H(r["CreatedByName"])+"</dd><dt>สถานะ</dt><dd>"+H(r["Status"])+"</dd><dt>เหตุผล Return</dt><dd>"+H(r["ReturnReason"])+"</dd></dl>";repImages.DataSource=service.Attachments(id,AssetAccess);repImages.DataBind();pnlDetail.Visible=true;}}catch(Exception ex){lblMessage.Text=Server.HtmlEncode(ex.Message);}}
protected void Close_Click(object s,EventArgs e){pnlDetail.Visible=false;}protected void Export_Click(object s,EventArgs e){var t=Data();Response.Clear();Response.ContentType="application/vnd.ms-excel";Response.AddHeader("Content-Disposition","attachment;filename=AssetSurvey-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".xls");var b=new StringBuilder();foreach(DataColumn c in t.Columns)b.Append(c.ColumnName).Append('\t');b.AppendLine();foreach(DataRow r in t.Rows){foreach(var v in r.ItemArray)b.Append(Convert.ToString(v).Replace("\t"," ")).Append('\t');b.AppendLine();}Response.ContentEncoding=Encoding.UTF8;Response.Write("\uFEFF"+b);Response.End();}private string H(object v)=>Server.HtmlEncode(Convert.ToString(v));}}
